Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='publicfamily', at=datetime(2026, 10, 25, 0, 0, 0), actor='assistant', title="Public repositories live in the fulfilium organization, private ones under the owner's account", body="The repositories meant for the public, such as prodrome, suzatary-core and each project's roadmap, live in the fulfilium organization on GitHub. The development repository, the data repository and the core archive stay under the owner's own account and stay private. A fine-grained token has one resource owner, so every push token is minted for one owner and for the fewest repositories it needs, and no token spans the owner's private repositories and the organization's public ones.", rationale='With the two families under different owners, a leaked public push token cannot reach private data, and the public family can be granted, watched and published on its own terms.', supersedes=()))